        "cycles": raw[0xC19],
        "main_v": raw[0xC1A],
        "main_a": raw[0xC1B],
        "complete_v": raw[0xC1C],
        "complete_a": raw[0xC1D],
        "select_v": raw[0xC1E],
        "select_a": raw[0xC1F],
        "lookup_hit_v": raw[0xC20],
        "lookup_miss_v": raw[0xC21],
        "lookup_hit_a": raw[0xC22],
        "lookup_miss_a": raw[0xC23],
