def _paired_comparisons(cases, selection, group_key):
    """Same-round, same-target paired differences against the fixed-gap baseline."""
    by_key = {}
    for item in cases:
        if item["status"] != "ok" or not item.get("metrics"):
            continue
        if item["phase"] != group_key:
            continue
        by_key[(item["method"], item["target"], item["block"])] = item
    methods = sorted({key[0] for key in by_key})
    targets = sorted({key[1] for key in by_key if key[1] is not None})
    comparisons = []
    for method in methods:
        if method == "fixedgap":
            continue
        for target in targets:
            pairs = []
            for block in sorted({key[2] for key in by_key if key[1] == target}):
                left = by_key.get((method, target, block))
                right = by_key.get(("fixedgap", target, block))
                if not left or not right:
                    continue
                left_a = left["metrics"].get("a_mib_s")
                right_a = right["metrics"].get("a_mib_s")
                if left_a is None or right_a is None:
                    continue
                pairs.append(left_a - right_a)
            matched = _selection_matched(selection, method, target)
            entry = {
                "group": group_key,
                "method": method,
                "target": target,
                "paired_rounds": len(pairs),
                "matched": matched,
            }
            if pairs:
                entry["difference_a_mib_s"] = _bootstrap_ci(pairs)
            if not matched:
                entry["gain_claim"] = "none (selection is unmatched; no protection gain may be claimed)"
            elif pairs:
                entry["gain_claim"] = "engineering reference only, never significance"
            else:
                entry["gain_claim"] = "none (no complete pairs)"
